# --- DATA: HalDiskCachePartitionCount ------------------------------------- #
# Count of HDD cache partitions (X:, Y:, Z: on retail).  Titles register
# themselves with the cache-partition assignment array stored at
# partition0:0x800.  A zero value computes count-1 = -1 and produces a
# fatally large memcpy in some titles' registration code.
40   =3

